<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Kanban Board</title>
  <style>
    :root {
      --bg: #f4f6fb;
      --surface: #ffffff;
      --text: #172033;
      --muted: #6d7890;
      --border: #e4e8f0;
      --accent: #5967e8;
      --accent-dark: #4654d4;
      --shadow: 0 12px 30px rgba(26, 38, 74, 0.08);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      background: var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .app {
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
      padding: 48px 0 56px;
    }

    .topbar {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 32px;
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(2rem, 4vw, 3rem);
      letter-spacing: -0.05em;
    }

    .subtitle {
      margin: 0;
      color: var(--muted);
      font-size: 0.98rem;
    }

    .composer {
      display: flex;
      width: min(440px, 100%);
      gap: 10px;
    }

    #new-card {
      min-width: 0;
      flex: 1;
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 13px 15px;
      color: var(--text);
      background: var(--surface);
      font: inherit;
      outline: none;
      box-shadow: 0 4px 12px rgba(26, 38, 74, 0.03);
    }

    #new-card:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(89, 103, 232, 0.14);
    }

    #add-card {
      border: 0;
      border-radius: 12px;
      padding: 0 19px;
      background: var(--accent);
      color: white;
      cursor: pointer;
      font: inherit;
      font-weight: 700;
      transition: background 0.2s, transform 0.2s;
    }

    #add-card:hover {
      background: var(--accent-dark);
      transform: translateY(-1px);
    }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 20px;
      align-items: start;
    }

    .column {
      min-height: 420px;
      padding: 18px;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.68);
      transition: border-color 0.2s, background 0.2s;
    }

    .column.drag-over {
      border-color: var(--accent);
      background: rgba(89, 103, 232, 0.07);
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 16px;
    }

    .column-title {
      margin: 0;
      font-size: 1rem;
      font-weight: 800;
      letter-spacing: -0.01em;
    }

    .count {
      display: inline-grid;
      min-width: 28px;
      height: 28px;
      place-items: center;
      border-radius: 999px;
      background: #e9ecff;
      color: var(--accent-dark);
      font-size: 0.82rem;
      font-weight: 800;
    }

    .card-container {
      display: grid;
      gap: 12px;
      min-height: 340px;
    }

    .card {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 15px;
      border: 1px solid var(--border);
      border-radius: 13px;
      background: var(--surface);
      box-shadow: var(--shadow);
      cursor: grab;
      user-select: none;
    }

    .card:active {
      cursor: grabbing;
    }

    .card.dragging {
      opacity: 0.45;
    }

    .card-title {
      overflow-wrap: anywhere;
      line-height: 1.4;
      font-weight: 650;
    }

    .card-del {
      flex: 0 0 auto;
      width: 28px;
      height: 28px;
      border: 0;
      border-radius: 8px;
      background: transparent;
      color: #9aa4b8;
      cursor: pointer;
      font-size: 1.15rem;
      line-height: 1;
    }

    .card-del:hover {
      background: #fff0f1;
      color: #d84d5b;
    }

    @media (max-width: 800px) {
      .topbar {
        align-items: stretch;
        flex-direction: column;
      }

      .composer {
        width: 100%;
      }

      .board {
        grid-template-columns: 1fr;
      }

      .column {
        min-height: 220px;
      }

      .card-container {
        min-height: 90px;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <section class="topbar">
      <div>
        <h1>Project board</h1>
        <p class="subtitle">Organize work, keep momentum, and ship with clarity.</p>
      </div>

      <form class="composer" id="card-form">
        <input id="new-card" type="text" placeholder="What needs to be done?" autocomplete="off" />
        <button id="add-card" type="submit">Add card</button>
      </form>
    </section>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo" data-column="todo">
        <div class="column-header">
          <h2 class="column-title">To Do</h2>
          <span class="count" aria-label="To Do card count">0</span>
        </div>
        <div class="card-container"></div>
      </section>

      <section class="column" id="col-doing" data-column="doing">
        <div class="column-header">
          <h2 class="column-title">Doing</h2>
          <span class="count" aria-label="Doing card count">0</span>
        </div>
        <div class="card-container"></div>
      </section>

      <section class="column" id="col-done" data-column="done">
        <div class="column-header">
          <h2 class="column-title">Done</h2>
          <span class="count" aria-label="Done card count">0</span>
        </div>
        <div class="card-container"></div>
      </section>
    </section>
  </main>

  <script>
    (() => {
      const storageKey = "kanban-board-state";
      const columns = [...document.querySelectorAll(".column")];
      const form = document.getElementById("card-form");
      const input = document.getElementById("new-card");
      let draggedCard = null;

      function createId() {
        return "card-" + Date.now() + "-" + Math.random().toString(36).slice(2);
      }

      function saveBoard() {
        const state = {};
        columns.forEach((column) => {
          state[column.dataset.column] = [...column.querySelectorAll(".card")].map((card) => ({
            id: card.dataset.id,
            title: card.querySelector(".card-title").textContent
          }));
        });
        localStorage.setItem(storageKey, JSON.stringify(state));
      }

      function updateCounts() {
        columns.forEach((column) => {
          column.querySelector(".count").textContent =
            column.querySelectorAll(".card").length;
        });
      }

      function addCard(title, columnKey = "todo", id = createId()) {
        const card = document.createElement("article");
        card.className = "card";
        card.draggable = true;
        card.dataset.id = id;

        const cardTitle = document.createElement("span");
        cardTitle.className = "card-title";
        cardTitle.textContent = title;

        const deleteButton = document.createElement("button");
        deleteButton.className = "card-del";
        deleteButton.type = "button";
        deleteButton.setAttribute("aria-label", "Delete " + title);
        deleteButton.textContent = "×";
        deleteButton.addEventListener("click", () => {
          card.remove();
          updateCounts();
          saveBoard();
        });

        card.append(cardTitle, deleteButton);
        card.addEventListener("dragstart", (event) => {
          draggedCard = card;
          card.classList.add("dragging");
          event.dataTransfer.effectAllowed = "move";
          event.dataTransfer.setData("text/plain", card.dataset.id);
        });
        card.addEventListener("dragend", () => {
          card.classList.remove("dragging");
          draggedCard = null;
          columns.forEach((column) => column.classList.remove("drag-over"));
        });

        const destination = document.querySelector(
          `.column[data-column="${columnKey}"] .card-container`
        ) || document.querySelector("#col-todo .card-container");
        destination.appendChild(card);
      }

      function loadBoard() {
        let state = null;
        try {
          state = JSON.parse(localStorage.getItem(storageKey));
        } catch (_) {
          state = null;
        }

        if (state && typeof state === "object") {
          Object.entries(state).forEach(([columnKey, cards]) => {
            if (!Array.isArray(cards)) return;
            cards.forEach((item) => {
              if (item && typeof item.title === "string") {
                addCard(item.title, columnKey, item.id || createId());
              }
            });
          });
        }

        updateCounts();
      }

      columns.forEach((column) => {
        column.addEventListener("dragover", (event) => {
          event.preventDefault();
          event.dataTransfer.dropEffect = "move";
          column.classList.add("drag-over");
        });

        column.addEventListener("dragleave", (event) => {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", (event) => {
          event.preventDefault();
          column.classList.remove("drag-over");
          if (!draggedCard) return;
          column.querySelector(".card-container").appendChild(draggedCard);
          updateCounts();
          saveBoard();
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) return;
        addCard(title);
        input.value = "";
        updateCounts();
        saveBoard();
        input.focus();
      });

      loadBoard();
    })();
  </script>
</body>
</html>
